import{_t as e,at as t,et as n,it as r,n as i,ot as a,rt as o,xt as s}from"./chunks/framework.C5Z6qjff.js";var c=JSON.parse(`{"title":"Logging in","description":"","frontmatter":{"title":"Logging in","covers":{"screens":[],"stories":["US-001","US-005"]}},"headers":[],"relativePath":"usage/login.md","filePath":"usage/login.md"}`),l={name:`usage/login.md`};function u(i,c,l,u,d,f){let p=s(`Screenshot`);return e(),o(`div`,null,[c[0]||=r(`<h1 id="logging-in" tabindex="-1">Logging in <a class="header-anchor" href="#logging-in" aria-label="Permalink to “Logging in”">​</a></h1><p>Open the web interface and choose <em>Log in</em>. The page <em>Log in to OEA</em> offers one button <em>Log in with …</em> per identity provider of your organization and, below it, the login with the local system admin account.</p><h2 id="log-in-through-your-identity-provider" tabindex="-1">Log in through your identity provider <a class="header-anchor" href="#log-in-through-your-identity-provider" aria-label="Permalink to “Log in through your identity provider”">​</a></h2><ol><li>Choose <em>Log in with</em> and the name of your provider.</li><li>Log in at your provider as usual; it sends you back to OEA.</li><li>You are logged in. The header shows <em>Catalogs</em>, your profile and <em>Log out</em>.</li></ol><p>Your administrator must have created your person and bound it to your identity at the provider. If that is not the case, the login page shows <em>Login failed</em> – for safety, without the exact reason; your administrator finds it in the audit log. If the provider is not reachable, the page asks you to try again later.</p><p>Your roles come from your groups at the provider. Roles with administrative permissions apply only if you logged in with a second factor at the provider.</p><h2 id="log-in-with-the-local-system-admin-account" tabindex="-1">Log in with the local system admin account <a class="header-anchor" href="#log-in-with-the-local-system-admin-account" aria-label="Permalink to “Log in with the local system admin account”">​</a></h2><p>Enter the login name and password of the system admin account and choose <em>Log in</em>. After the setup phase, the page asks for the code of your authenticator app: enter it and choose <em>Confirm</em>. <em>Start again</em> returns to the password step.</p>`,8),a(p,{name:`login`,alt:`Login page with the providers and the login of the local system admin account`}),c[1]||=r(`<ul><li>After five wrong codes, you have to start again with the password.</li><li>After repeated wrong passwords, further attempts are delayed (at most 15 minutes).</li><li>Every login and every failed attempt – through a provider or with the local account – is recorded in the audit log with time, mechanism and result (<code>auth.login</code>, <code>auth.login-failed</code>); a failed attempt names the internal reason only there.</li></ul><h2 id="your-profile" tabindex="-1">Your profile <a class="header-anchor" href="#your-profile" aria-label="Permalink to “Your profile”">​</a></h2><p><em>Profile</em> (<code>/me</code>) shows your name, the account type, whether your session is confirmed with a second factor, and your roles. If no role is assigned to you yet, the profile tells you so; ask an administrator for access.</p><h2 id="set-up-a-second-factor" tabindex="-1">Set up a second factor <a class="header-anchor" href="#set-up-a-second-factor" aria-label="Permalink to “Set up a second factor”">​</a></h2><p>The local system admin account needs a second factor to end the setup phase (see <a href="./../setup/first-administrator">First administrator</a>):</p><ol><li>In <em>Profile</em>, choose <em>Set up a second factor</em>, then <em>Set up authenticator app</em>.</li><li>Scan the QR code with an authenticator app (any app for time-based one-time passwords, TOTP).</li><li>Enter the code from the app under <em>Code from the app</em> and choose <em>Confirm</em>.</li></ol>`,6),a(p,{name:`second-factor-enroll`,alt:`Setting up the authenticator app with QR code and code field`}),c[2]||=n(`p`,null,`The page confirms that the authenticator app is set up and the session is confirmed. Setting up a second factor needs a login within the last 5 minutes; otherwise, the page asks you to log in again.`,-1),c[3]||=n(`h2`,{id:`sessions-and-logging-out`,tabindex:`-1`},[t(`Sessions and logging out `),n(`a`,{class:`header-anchor`,href:`#sessions-and-logging-out`,"aria-label":`Permalink to “Sessions and logging out”`},`​`)],-1),c[4]||=n(`p`,null,[t(`Choose `),n(`em`,null,`Log out`),t(` in the header or in your profile. A session also ends after 30 minutes without activity and at the latest 12 hours after the login.`)],-1)])}var d=i(l,[[`render`,u]]);export{c as __pageData,d as default};